-- Rifts World Book 19: Australia - its bestiary and its notable NPCs.
-- 4 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~101-australia-race-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 creatures are in' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE slug IN ('kwarla', 'mokoloi', 'outback-mutie', 'shadow-people');
SELECT 'and 4 of them are playable' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('kwarla', 'mokoloi', 'outback-mutie', 'shadow-people');
SELECT 'the creatures carry 20 attacks' AS assertion, count(*) AS got, 20 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('kwarla', 'mokoloi', 'outback-mutie', 'shadow-people');

