INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('kwarla', 'Kwarla', 'humanoid', 'rifts', 1, 'Any, but most are Principled, Scrupulous or Unprincipled, and now and then Aberrant', '{"IQ":"2D6+1","ME":"2D6+10","MA":"3D6+2","PS":"3D6+12","PP":"2D6+10","PE":"2D6+12","PB":"1D6+8","Spd":"3D6+6"}', NULL, NULL, 'PE', '4D6+22', 'ME', 'M.D.C. is the P.E. number, +1D6 per level. I.S.P. is the M.E. number, +1D6 per level; a female adds 2D6 once. Supernatural P.S. and P.E. Heals 2D4 M.D.C. per 24 hours, twice that with full rest or a day of meditation. Increase M.D.C.: 5 P.P.E. and one action triples M.D.C. until the extra is used up or 20 minutes per level pass.', NULL, 8, '{"initiative":3,"dodge":1,"pull_punch":3}', '+3 to save vs toxins and ingested poisons, +7 vs possession, +5 vs Horror Factor, +1 vs Ritual Magic. Horror Factor works ONLY on evil supernatural beings and evil sorcerers: 8 for one Kwarla, 11 for three or more. Damage is by claws and Supernatural P.S., or by weapon.', 'Natural: climb 95/85%, swim 60%, prowl 50%. Male Demon Hunters: Hand to Hand: Expert, Boxing, W.P. Blunt, W.P. Axe, two ancient W.P.s of choice, Lore: Demons and Monsters (+25%), Lore: Dreamtime Culture (+20%), Detect Ambush (+10%), Intelligence (+5%), Track humanoids and the supernatural (+15%), Dance (+10%), Speak Aboriginal (+30%), Speak English (+10%), Outback Survival (+30%), and every other Wilderness skill (+15%) except Use Songlines and Roadwise. Female Providers: Lore: Demons and Monsters (+20%), Lore: Dreamtime Culture (+15%), one Lore of choice (+15%), Escape Artist (+10%), Dance (+15%), Sing (+15%); Cook, Fishing, Identify Plants and Fruits, Preserve Food, Skin and Prepare Animal Hides, Land Navigation, Camouflage and Outback Survival at +20%; Speak Aboriginal (+30%), Speak English (+10%), Basic Math (+20%), General Repair and Maintenance (+15%), Hand to Hand: Basic, one ancient W.P. A civilized Rogue Kwarla halves those bonuses and adds one piloting skill, three technical skills without bonus and one modern W.P.', 'Nightvision 200 feet (61 m) and good hearing. Leaps 8 feet (2.4 m) up and 12 feet (3.6 m) across. A born enemy of the undead: a vampire''s slow kill bite and mind control do nothing to it, nor does the mind control of demons and similar supernatural hunters, though ordinary spell casting by mortal races still works. Razor claws and a weak bite (see attacks). Claws of Vengeance: for 1 P.P.E. against a magical or supernatural opponent the claws lengthen into energy blades of short sword size, which can cut magic armor and parry magic weapons.', 'None, unless a Kwarla Mystic', 'Minor psionic. Males pick 1D4 Physical powers; females pick 1D4+1 Sensitive or Healing powers.', '3 feet plus 3D6 inches (0.9 to 1.37 m)', '220 + 6D6 pounds (110.3 to 121.5 kg)', '60 + 2D6 years', 'Heavy forest, rainforest and thick bushland', 'Other tribal peoples; Bushmen, rugged Jackaroos, and human or D-Bee heroes who fight the supernatural', 'Supernatural evil of every kind; most white humans and D-Bees who damage nature. Demons, Necromancers and dark mages wear Kwarla hides and skulls.', 'The book stats the race under the Kwarla Demon Hunter R.C.C. heading as an NPC or optional player character. Males are Demon Hunters or else Kwarla Mystics (a separate R.C.C.); every female is a Provider. With G.M. consent a civilized Rogue Kwarla may be played. No equipment or money is listed.', 'The Koala people: squat, very heavy, fur-covered tree dwellers with black claws, counted as creatures of magic. Tribal and peaceful toward nature, blunt and unable to see the use of a lie, they hunt demons and other supernatural evil by instinct and favor ambush from the branches.', 'Rifts World Book 19: Australia p.132-135'),
('mokoloi', 'Mokoloi', 'alien', 'rifts', 1, 'Any, but 20% are Aberrant', '{"IQ":"2D6+6","ME":"2D6+6","MA":"2D6+8","PS":"4D6+8","PP":"2D6+6","PE":"3D6+6","PB":"2D6","Spd":"5D6"}', NULL, NULL, 'PE+2D4x10', '6D6', NULL, 'M.D.C. is the P.E. number plus 2D4x10, +2D6 per level. On an S.D.C. world: Hit Points P.E. x5, +2D6 per level, and 1D6x10+25 S.D.C. P.P.E. 6D6, more for a practitioner of magic. Supernatural P.S. and P.E. Spd is quadrupled swimming underwater. Bio-regenerates 2D6 M.D. per hour; lost limbs regrow in 3D4+4 months.', NULL, 12, NULL, 'Save vs Horror Factor: males +3, females +4. Mokoloi Martial Arts (males only; females fight as Hand to Hand: Expert) is standard Martial Arts plus +2 initiative, +3 pull punch, +1 attack with the tail, +1 attack underwater and +2 dodge underwater. Roll-over (any Hand to Hand skill, after a grapple): crush/squeeze damage three times a round; the victim is -2 on all combat moves, loses initiative and all attacks, and breaks free on a roll of 17 or better, which uses two actions. Vulnerability: dry heat. Without full immersion in water at least every other day it is -2 to dodge, parry and initiative and loses 1 M.D.C. a day.', 'Speaks Mokoloi 98%, Swim 98%; most also speak one or two Australian languages (+15%). Other skills by O.C.C.', 'Nightvision 200 feet (61 m); sees through murky water and in infrared and ultraviolet, with fine sight above and below the surface and human-grade hearing. While submerged it feels anything heavier than 10 pounds (4.5 kg) moving on the surface inside 300 feet (91.5 m), and can place where it went in and judge heading and speed (60% +3% per level). Swims by instinct, stays under one minute per point of current M.D.C., and tolerates depths to 600 feet (183 m). Whatever its strength it may choose a tail strike, kick or claw swipe of at least 2D6 M.D. and hold back the Supernatural P.S. damage.', 'By O.C.C. About 12-15% of females know Stone Magic; about 5% of males and a further 10% of females are Ley Line Walkers, typically level 1D4+2.', 'Standard, the same chance as a human (Rifts RPG p.12)', '6-7 feet (1.8 to 2.1 m) standing; 12-15 feet (3.6 to 4.6 m) long with the 5-6 foot tail', '250 + 6D10 lb (115 to 139.5 kg)', '45 years; some reach 70', 'Swampy wetlands, so far mostly the Northland; about 15,000, 45% female', 'The Horune Pirates (a new trading partner, not yet a true ally) and some mutant bands, non-mammals for preference', 'The armies of the two Tech-Cities; vampires, demons and the supernatural in general; wary of the Aboriginal tribes and contemptuous of mammals', 'Headed an NPC villain and optional player R.C.C. that takes an O.C.C. Females: Stone Master, Techno-Wizard and Ley Line Walker are the usual choices, and any other magic is open except Shifter, Warlock, Witch, Druid and anything that needs a supernatural patron; also scholar, theologian, healer or builder. Males: Ley Line Walker is the only usual magic, and no Juicer, Borg or M.O.M. conversion; typically Headhunter, Wilderness Scout, Commando/Special Forces, Military Specialist, Bandit, Grunt/Warrior, Bounty Hunter, Roadganger, Power Armor Pilot, or an Outback O.C.C. such as Bushman or Songjuicer. Rogue Scholar, Body Fixer and Operator equivalents exist too.', 'Crocodile Men or Man-Crocs: tailed reptilian aliens whose ancestors reached northern Australia by rift. They build stone swamp cities with pyramids, are governed by councils on which females predominate, trust magic above machines, and never teach their Techno-Wizardry or Stone Magic to outsiders. Hot tempered and supremacist, yet scrupulous about repaying a debt.', 'Rifts World Book 19: Australia p.137-142'),
('outback-mutie', 'Outback Mutie', 'mutant', 'rifts', 1, 'Any', NULL, NULL, NULL, NULL, NULL, NULL, 'The entry prints NO attribute dice, Hit Points, S.D.C., P.P.E. or I.S.P.: mutants are Australian-born humans, so the human figures of the Rifts RPG apply, and none is stored here. From the tables: Nate and Magic Back Rounder count Hit Points as M.D.C.; a Nate has P.P.E. 6D6 + P.E., +2D6 per level; a Tanker has 4D4x10 + P.E. M.D.C., +2D6 per level, Supernatural P.S., and recovers 2D6 M.D.C. per 24 hours; Minor M.D.C. turns Hit Points into M.D.C.; Major M.D.C. turns Hit Points +1D4x10 into M.D.C.; an Ecto-Freak adds 4D6 I.S.P.', NULL, NULL, NULL, 'None printed for the R.C.C. itself; every bonus comes from the three mutation tables (see natural abilities). Natural A.R. only by deformity: snake 10, lizard 12, crocodile-like 13, echidna 14.', 'Common Outback Skills: Speaks Australian 80% +2D4% (most are illiterate), two Domestic of choice (+10%), Land Navigation (+10%), Law (+10%), two Lores of choice (+10%), Horsemanship: General or Pilot Automobile, Truck or Motorcycle (+10%, pick one), General Athletics, W.P. Energy Rifle, three W.P.s of choice, Hand to Hand: Basic (Expert for one related skill; Martial Arts, or Assassin if evil, for two). Related skills: six at level one, three at level two, one each at levels 3, 6, 9 and 12. Secondary skills: two at levels 1, 3, 6, 8 and 11.', 'Roll or pick once on each of three tables. PHYSICAL DEFORMITY: 01-05 looks human. 06-08 tall and thin, 6 ft +3D6 inches. 09-10 hunched wallaby or bettong build. 11-15 third arm, +1 attack. 16-20 limbs of several animals. 21-25 snake: no legs, a 1D4+3 ft serpent body, Spd 1D6+6, A.R. 10, prowl 50% +4%/level; half have withered arms, -15% on hand skills. 26-30 koala: 4-5 ft, climbs at +10%. 31-35 platypus: -4 Spd, swims at +10%, shrugs off cold, 1D4+3 minutes on one breath, depth 300 ft (91 m); the furred, duck-billed half are -3 P.B. 36-45 feline: half have retractable claws, +1D4 P.S. and P.P. and natural acrobatics; a third get +8 P.B. and +1D4+1 on one other physical attribute. 46-55 canine: half get +1D4 P.S., +1D6+2 Spd and scent tracking at 40% +5%/level; a third get +8 M.A. and +1D4+2 on one physical attribute. 56-65 bat: half are -2 Spd with amplified hearing, +1 parry, +2 dodge, +3 initiative. 66-75 kangaroo or wallaby: +1D6 Spd, leaps 6 ft up and 10 ft across; half instead +1D6+6 Spd, 10 ft up and 15 ft across, 20% more from a run. 76-80 lizard: climbs at +10%; half A.R. 12 and +2D6 S.D.C.; 20% crocodile-like, A.R. 13 and +2D6+6 S.D.C. 81-85 bandicoot or bilby: 4.5-5 ft, nightvision 600 ft (183 m), +1D4 Spd. 86-90 Tasmanian devil: nightvision 300 ft (91.5 m), +1D4 P.S. and Spd. 91-95 thylacine: +2D6 Spd, +2 P.S. 96-00 echidna: the quilled half have A.R. 14 and stab grapplers. ADDITIONAL SPECIAL ABILITIES: 01-10 +1D4+4 I.Q. 11-20 +2 initiative, +1 attack. 21-30 +1D4 P.S. 31-40 minor M.D.C. creature, +2 on one attribute. 41-50 major M.D.C. creature. 51-55 immune to disease and poison; drugs and potions work at half. 56-60 Blend 78%, Camouflage 70%, Escape Artist 50%, each +2%/level. 61-65 Swim 80% +2%/level, 1D4x10 minutes on one breath, depth 500 ft (152 m), double swim speed for four hours untired. 66-70 Acrobatics and Climbing at +20%. 71-80 +22 Spd, top speed for 30 minutes/level untired, +1 P.S. and P.E. 81-85 fireproof, M.D. and magic fire included. 86-90 Energy Expulsion. 91-00 wings: flies 20 mph (32 km), doubled for a bat mutant. The Special Mutant Powers table is under psionics and magic.', 'Special Mutant Powers 61-80, Natural Spell Caster (a Nate): one common wizard spell from each of spell levels 1-6, then one more per level of experience, of a spell level equal to the character''s own. Uses magic items by instinct, heals at ley lines as Ley Line Rejuvenation, +2 vs spell magic, +3 vs Horror Factor, +4 vs possession. 81-90 Magic Back Rounder: no charm, control, curse, illusion, sickness or helpful magic affects it, nor do Ley Line Storms; magic weapons and damaging spells do one tenth damage.', 'Special Mutant Powers: 01-05 a Mind Bleeder (roll that R.C.C.). 06-10 a Mind Melter (roll that R.C.C.). 11-20 Psi-Healer: all Healing powers plus 1D4 Sensitive or Physical. 21-30 Psychic Prognosticator (Psike-Eyes): Clairvoyance, Commune with Spirits, See the Invisible, See Aura, Read Dimensional Portal, Remote Viewing, Object Read, Psychic Diagnosis, Detect Psionics, Mind Block, two Sensitive of choice; Mind Bolt at level 4, Mind Bond at 8, Omni-Sight at 12; master psychic. 31-40 Psychic Fighter (Zap-Sack): Intuitive Combat, Sixth Sense, Electrokinesis or Pyrokinesis, two offensive Super powers, two Physical powers per level from level two; master psychic. 41-50 Ectoplasmic Master (Ecto-Freak): all ectoplasmic powers at double duration and range with 10% more S.D.C., Levitate, 1D4 Physical and 1D4 Sensitive; major psychic, +4D6 I.S.P. 51-55 Psychic Sensitive (Feelie): two Sensitive powers per level, plus two of Empathic Transmission, Mentally Possess Others, Mind Bolt, Mind Block Auto-Defense, Radiate Horror Factor, Telemechanic Operation, Psychic Omni-Sight; master psychic. 56-60 TK-Master (Mover): all telekinetic Physical powers, Psychic Body Field, Telekinesis (Super), Telekinetic Force Field, two Physical of choice; master psychic. 61-00 are not psionic (Nate, Magic Back Rounder, Tanker).', NULL, NULL, NULL, 'The Australian Outback; only humans born in Australia mutate', 'Aboriginal tribes, who honor well-meaning mutants as good Animal Men spirits; many Outback communities, which accept them as equals', 'City-Goers, Roadgangers and other intolerant groups; the Tech-Cities'' Phreaker soldiers treat Outback Muties as high priority threats', 'An R.C.C. with its own skill list, open to any mutant with no attribute requirement; the city-born mutant has the Phreaker Military Grunt R.C.C. instead. Starts with travelling and Sunday clothes, light to medium homemade M.D.C. armor, an S.D.C. sidearm, one weapon per W.P. with 1D4 clips, and camping gear; no vehicle; 2D6x100 dollars plus 1D6x100 in trade goods. No cybernetics. The G.M. may swap in other animals, or the Psyscape psychic classes.', 'A human mutant of the Outback, where Mutie is a plain word and not an insult. Most show some animal feature and about half look more beast than human; nearly all carry a psionic or magical gift. Outback towns often count them as neighbors, lawmen and leaders, and Phreaker is kept for evil mutants and city ones. Nobody has proved what causes the mutation.', 'Rifts World Book 19: Australia p.126-131'),
('shadow-people', 'Shadow People', 'faerie', 'rifts', 1, 'Any, but most are Scrupulous or Unprincipled; an evil one is very rare', '{"IQ":"3D6","ME":"2D6+1","MA":"3D6+6","PS":"2D6","PP":"3D6","PE":"3D6","PB":"2D6+3","Spd":"3D6+3"}', NULL, NULL, 'PE+4D6', 'PEx5', NULL, 'M.D.C. is the P.E. number +4D6 to start, +1D6 per level. On an S.D.C. world: Hit Points P.E. +1D6 per level, 6D6 S.D.C. and a natural A.R. of 9. P.P.E. is the P.E. number x5 plus 5D6 per level; the page does not say the 5D6 is rolled to start, so the formula holds the P.E. x5 alone. Bio-regenerates 2D6 M.D.C. every 12 hours. Average NPC level 1D4+3.', NULL, NULL, '{"attacks":2,"dodge":1,"pull_punch":2,"roll":2}', 'Two attacks per round untrained, or as per a Hand to Hand skill. +3 to save vs poison/toxins; the +2 roll is the save vs punch, fall or impact. At night or in the dark: +3 initiative, a further +1 dodge and +15% prowl. Horror Factor: none. Vulnerability, magic: on a Songline or ley line, or in a magic circle, magical sanctuary or anti-magic cloud, it cannot enter shadows, vanish in the dark or slide into cracks, and its spells have half strength. Magic spells, magic weapons and the physical attacks of creatures of magic (not supernatural beings) do double damage. A Ley Line Storm within 100 miles (160 km) shuts the powers off.', 'Natural: climb 98%/88%. R.C.C. skills: Prowl, Blend, Outback Survival, Land Navigation and Speak Aborigine, all at +20%; two Ancient W.P.s; three skills from Espionage (+10%) or Physical (any); three from Wilderness or Domestic (+10%). Native tongue is a dialect of Faerie Speak (-20% to Faerie speakers).', 'Nightvision 2000 feet (614 m). Step into Rock: free and automatic, one action to flatten and one more to slide into any crack in stone or earth that is at least three feet (0.9 m) long, however narrow. Become Two-Dimensional: for 10 P.P.E., at will and for as long as wanted, self and gear turn into a flat picture as the Temporal spell D-Shift: Two Dimensions (Rifts England): unseen by thermal, heat and motion sensors, hide 85%, one sixteenth weight, able to cling to surfaces; blows and blasts do half when braced on a surface, gas does half, swallowed or injected drugs nothing; it cannot move, talk, eat or cast, and a wind can carry it off. Meld into Shadows: any part of the body in shade is invisible to the eye without a spell. Invisible in Darkness: unseen, silent and trackless in full dark unless a light is aimed straight at it; see the invisible fails. Infrared and thermo-imaging defeat both.', 'All know See the Invisible, Concealment, Detect Concealment, Armor of Ithan, Mystic Fulcrum, Cloak of Darkness and Shadow Meld, plus six common wizard spells of choice from levels 1-4 OR three Temporal Magic spells from levels 7-9. Understands Songlines but cannot use them.', 'None', 'At least 6 feet plus 2D6+1 inches (1.91-2.16 m)', '50-75 lbs (22.5 to 33.8 kg)', 'Unknown; at least 1,000 years and perhaps ten times that. Hibernates without aging while magic is low.', 'Large rocks, craggy hills, canyons, bluffs and mountains of the drier north, mostly the Rim territories; never within 200 miles (320 km) of a Tech-City. Thought to number under 10,000.', 'Aboriginal tribes and some Outbacker humans; leaning favorably toward the Kwarla', 'Any enemy of the Millennium Trees or the Dreamtime, most demons and evil forces included', 'Headed an NPC or optional player character, played only if the G.M. agrees. A full R.C.C. with its own skills and no O.C.C.; the book lists no equipment or money. A player character is usually young and adventurous, or a nervous one travelling out of duty.', 'Australian faerie folk who live in pocket dimensions inside cracks in boulders and hillsides, in families of three to seven. Shy, gentle plant eaters and old friends of the Aborigines, too frail to brawl, they fight by stealth, traps, scares and magic and would sooner drive a foe off than kill it.', 'Rifts World Book 19: Australia p.148-151');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'kwarla', 'Claws', '1D6 M.D. plus Supernatural P.S. damage', 1, NULL, 'Average P.S. is 21-25, a 2D6 M.D. punch.', 0),
('creature', 'kwarla', 'Bite', '2D6 S.D.C.', 0, NULL, 'S.D.C./Hit Point damage.', 1),
('creature', 'kwarla', 'Claws of Vengeance', '4D6 M.D. plus Supernatural P.S. damage', 1, NULL, '1 P.P.E.; only against magical or supernatural foes. Hit Point damage to vampires and were-creatures, double damage to alien intelligences and their avatars or essence fragments. Against mortals in M.D.C. armor, cyborgs and robots it does ordinary claw damage.', 2),
('creature', 'mokoloi', 'Bite (nip)', '5D6 S.D.C.', 0, NULL, 'S.D.C./Hit Point damage; rarely used except in self-defense.', 0),
('creature', 'mokoloi', 'Bite (full strength)', '1D6+2 M.D.', 1, NULL, NULL, 1),
('creature', 'mokoloi', 'Claw Swipe', 'Supernatural P.S. punch damage +2D6 M.D.', 1, NULL, 'May be delivered as a flat 2D6 M.D. minimum instead.', 2),
('creature', 'mokoloi', 'Restrained Punch', '4D6 S.D.C.', 0, NULL, 'Mokoloi Martial Arts (males).', 3),
('creature', 'mokoloi', 'Full Strength Punch', '2D6 M.D. plus Supernatural P.S. damage', 1, NULL, 'Mokoloi Martial Arts (males). Counts as two attacks.', 4),
('creature', 'mokoloi', 'Claw Strike', '4D6 M.D. plus Supernatural P.S. damage', 1, NULL, 'Mokoloi Martial Arts (males). Counts as two attacks.', 5),
('creature', 'mokoloi', 'Power Punch', 'Double Supernatural P.S. damage', 1, NULL, 'Mokoloi Martial Arts (males).', 6),
('creature', 'mokoloi', 'Restrained Kick', '4D6 S.D.C.', 0, NULL, 'Mokoloi Martial Arts (males).', 7),
('creature', 'mokoloi', 'Full Strength Karate-Style Kick', '4D6 M.D. plus Supernatural P.S. damage', 1, NULL, 'Mokoloi Martial Arts (males). Counts as two attacks.', 8),
('creature', 'mokoloi', 'Body Block/Tackle', '1D4 M.D.', 1, NULL, 'Mokoloi Martial Arts (males).', 9),
('creature', 'mokoloi', 'Head Butt', '1D4 M.D.', 1, NULL, 'Mokoloi Martial Arts (males).', 10),
('creature', 'mokoloi', 'Tail Slap', '2D6 M.D.', 1, NULL, 'Mokoloi Martial Arts (males).', 11),
('creature', 'mokoloi', 'Tail Strike', '3D6 M.D. plus Supernatural P.S. damage', 1, NULL, 'Mokoloi Martial Arts (males).', 12),
('creature', 'mokoloi', 'Crush/Squeeze', '3D6 direct to Hit Points, or 1D6 M.D. to a Mega-Damage creature', 0, NULL, 'Needs a grapple; each round the victim is held. The roll-over inflicts it three times a round.', 13),
('creature', 'outback-mutie', 'Energy Expulsion', '1D6 M.D. +2 M.D. per level of experience', 1, '200 feet (61 m) +40 feet (12.2 m) per level', 'Only with Additional Special Abilities 86-90. Fired from the eyes or hand.', 0),
('creature', 'outback-mutie', 'Retractable Claws (feline)', '2D6 + P.S. bonus', 0, NULL, 'Only the more feline half of Physical Deformity 36-45.', 1),
('creature', 'outback-mutie', 'Quills (echidna)', '1D6 S.D.C. per quill', 0, NULL, 'Only the quilled half of Physical Deformity 96-00. Anyone grabbing or wrestling the mutant takes 1D4+1 quills; M.D. if the mutant is an M.D. being.', 2);
INSERT INTO data_script_runs (filename) VALUES ('~101-australia-race-creatures.sql');
